/**
 * Just enough of the `vscode` module for patcher.js to be loaded and run outside
 * the editor. It is the one file that writes to somebody else's disk, and until
 * this stub existed it was also the only file with no test - which is how a build
 * that could not even load got as far as being handed over.
 */
let fakeExtensionPath = null;
module.exports = {
  __setClaudeCode(p) { fakeExtensionPath = p; },
  extensions: {
    getExtension(id) {
      if (id !== "anthropic.claude-code" || !fakeExtensionPath) return undefined;
      return { extensionPath: fakeExtensionPath, packageJSON: { version: "2.1.247" } };
    }
  }
};
